def hermitian_residual(matrix: sp.Matrix) -> sp.Matrix:
    result: list[sp.Expr] = []
    for row in range(4):
        result.append(sp.expand_complex(matrix[row, row]).as_real_imag()[1])
        for column in range(row + 1, 4):
            difference = sp.expand_complex(
                matrix[row, column] - sp.conjugate(matrix[column, row])
            )
            real, imaginary = difference.as_real_imag()
            result.extend((sp.expand(real), sp.expand(imaginary)))
    return sp.Matrix(result)


def lower_change(q: sp.Matrix) -> sp.Matrix:
    result = sp.eye(8)
    result[4:8, 0:4] = q
    return result


def pair_newton_system(
    first_propagator: sp.Matrix,
    third_propagator: sp.Matrix,
    q: sp.Matrix,
) -> tuple[sp.Matrix, tuple[sp.Matrix, ...], sp.Matrix, sp.Matrix]:
    """Rebuild M(Q)u=-r(Q) in the exact nilpotent involution fibre."""
    change = lower_change(q)
    inverse = sp.eye(8)
    inverse[4:8, 0:4] = -q
    seed = change * D * inverse
    directions: list[sp.Matrix] = []
    for row in range(4):
        for column in range(4, 8):
            elementary = sp.zeros(8)
            elementary[row, column] = 1
            direction = change * elementary * inverse
            directions.extend((direction, I * direction))

    rhs: list[sp.Expr] = []
    columns: list[list[sp.Matrix]] = [[], []]
    for position, propagator in enumerate(
        (first_propagator, third_propagator)
    ):
        use_seed = (
            seed
            if position == 0
            else prior.J * seed.conjugate() * prior.J
        )
        rhs.extend(
            -hermitian_residual(prior.E * use_seed * propagator * prior.F.T)
        )
        for direction in directions:
            use = (
                direction
                if position == 0
                else prior.J * direction.conjugate() * prior.J
            )
            columns[position].append(
                hermitian_residual(prior.E * use * propagator * prior.F.T)
            )
    system = sp.Matrix(
        32,
        32,
        lambda row, column: columns[row // 16][column][row % 16],
    )
    return seed, tuple(directions), system, sp.Matrix(rhs)


@dataclass(frozen=True)
class MinorData:
    minors: tuple[sp.Expr, ...]
    inertia: tuple[int, int, int]
    signs: str
    hermitian: bool


def exact_minor_data(matrix: sp.Matrix) -> MinorData:
    hermitian = base.matrix_equal(matrix, matrix.H)
    minors = tuple(
        sp.factor(matrix[:size, :size].det(method="domain-ge"))
        for size in range(1, 5)
    )
    sign_values = tuple(int(sp.sign(value)) for value in minors)
    nonzero = all(sign in (-1, 1) for sign in sign_values)
    inertia = (
        base.inertia_from_nonzero_leading_minors(minors)
        if hermitian and nonzero
        else (-1, -1, -1)
    )
    signs = "".join("+" if sign > 0 else "-" if sign < 0 else "0" for sign in sign_values)
    return MinorData(minors, inertia, signs, hermitian)


